import{loadProduct}from'../core/api.js';import{money}from'../core/format.js';import{toggleWish}from'../components/wishlist.js';import'../main.js';const id=new URLSearchParams(location.search).get('id')||'wlan-kabel';const p=await loadProduct(id).catch(()=>loadProduct('wlan-kabel'));document.title=p.name+' — Sehr Seriös';document.querySelector('[data-product]').innerHTML=`<div class="product-detail-visual"><span>${p.glyph}</span></div><div class="product-detail-info"><small>${p.category} · ★ ${p.rating}</small><h1>${p.name}</h1><p>${p.description}</p><h2>${money(p.price)}</h2><button class="btn btn-acid" data-add="${p.slug}">IN DEN WARENKORB →</button><button class="btn" data-wish>♡ MERKEN</button><hr><p class="muted">Theoretisch verfügbar · Versand irgendwann · 0 Jahre Garantie</p></div>`;document.querySelector('[data-wish]').onclick=()=>toggleWish(p.slug);
